SELECT CASE WHEN a.balance >= 84000 THEN 'high' WHEN a.balance >= 18000 THEN 'mid' ELSE 'low' END AS balance_bucket, DATE_TRUNC('MONTH', a.opened_date) AS opened_month, ROUND(STDDEV(t.amount), 2) AS stddev_amount FROM transactions t LEFT JOIN accounts a ON t.account_id = a.id GROUP BY CASE WHEN a.balance >= 84000 THEN 'high' WHEN a.balance >= 18000 THEN 'mid' ELSE 'low' END, DATE_TRUNC('MONTH', a.opened_date)
